// skTwLen is the length of StockhamTwiddles' table for a pass with ido >= 2.
func skTwLen(r, ido int) int {
	if r == 16 {
		return 2 * (r - 1) * ido
	}
	return (r - 1) * ido
}

// radix16Twiddles is StockhamTwiddles for radix 16: the same groups, but each
// twiddle stored as its halves pre-duplicated, so the kernel multiplies by
// them straight from memory. A group of g points stores, for j = 1..15, the g
// pairs (wr, wr), then the g pairs (wi, wi), each pair one complex128. It
// doubles the table, which Round 17 measured to cost the large transforms;
// radix 16 only runs up to 2048 points, and there it made the twiddled pass
// 7% faster on Zen 3 (2026-10-05).
func radix16Twiddles(ido, l1 int, root []complex128) (fwd, conj []complex128) {
	n := len(root)
	fwd = make([]complex128, 2*15*ido)
	conj = make([]complex128, len(fwd))
	at, i0 := 0, 0
	for _, g := range twGroups(ido) {
		for j := 1; j < 16; j++ {
			for i := i0; i < i0+g; i++ {
				w := root[(j*l1*i)%n]
				fwd[at] = complex(real(w), real(w))
				fwd[at+g] = complex(imag(w), imag(w))
				conj[at] = complex(real(w), real(w))
				conj[at+g] = complex(-imag(w), -imag(w))
				at++
			}
			at += g
		}
		i0 += g
	}
	return fwd, conj
}
